use std::io::{self,BufRead};fn main(){for l in io::stdin().lock().lines(){let l=l.unwrap();let w:Vec<_>=l.split_whitespace().collect();match w[0]{"half"=>{let v=f32::from_bits(u32::from_str_radix(w[1],16).unwrap());println!("{:04x}",half::f16::from_f32(v).to_bits());},"rng"=>{let seed=u64::from_str_radix(w[1],16).unwrap();let r=fastrand::Rng::with_seed(seed);let v=r.f32();println!("{:016x} {:08x}",r.get_seed(),v.to_bits());},_=>panic!()}}}
